"""Build concise MTH 101 sequence and series lessons from the supplied page images."""
import json
from pathlib import Path

root=Path(__file__).resolve().parents[1]
out=root/'supabase/content'
source='Fundamental Mathematics: Algebra, chapter 7, photographed pages 72–82, supplied 29 Oct 2026'
topics=[
 dict(title='Sequences, series and sigma notation',pages='72–73',idea='A sequence is an ordered list of terms U₁, U₂, … . A series is the sum of terms. A rule for Uₙ tells you which term appears in position n; sigma notation Σ adds the terms over a stated index range. Substitute each index separately before adding.',problem='Find the first three terms of Uₙ=n²+1 and evaluate Σ from n=1 to 4 of n².',steps=[(r'U_1=1^2+1=2','Put n=1 into the term rule.'),(r'U_2=2^2+1=5,\quad U_3=3^2+1=10','Repeat for the next two positions.'),(r'\sum_{n=1}^{4}n^2=1^2+2^2+3^2+4^2','Expand sigma notation into its four specified terms.'),(r'1+4+9+16=30','Add the evaluated terms.')],answer='The terms are 2, 5, 10; the sum is 30.',checks=[('For Uₙ=n²+1, what is U₄?',['5','9','16','17'],'D','Replace n by 4: U₄=4²+1=16+1=17. The subscript is the position, not a multiplier.'),('What is Σ from n=1 to 3 of (n²+1)?',['9','14','17','30'],'C','Expand the index range: (1²+1)+(2²+1)+(3²+1)=2+5+10=17. There are three terms, corresponding to n=1, 2 and 3.')]),
 dict(title='Arithmetic sequences and nth terms',pages='74–76',idea='An arithmetic progression adds the same difference d each time. With first term a, Uₙ=a+(n−1)d. To find d, subtract adjacent terms. To find an unknown position, set the formula equal to the given term and solve for n; the position must be a positive integer.',problem='Find the ninth term of 2, 7, 12, 17, … .',steps=[(r'a=2,\quad d=7-2=5','Read the first term and subtract two adjacent terms.'),(r'U_n=a+(n-1)d','Use the arithmetic nth-term formula.'),(r'U_9=2+(9-1)5','Substitute n=9, a=2 and d=5.'),(r'U_9=2+40=42','Calculate the eighth jump after the first term.')],answer='U₉=42.',checks=[('What is the sixteenth term of 2, 7, 12, …?',['72','77','82','87'],'B','The difference is 5, so U₁₆=2+(16−1)5=2+75=77. There are 15 jumps from the first term to the sixteenth.'),('Which term of −3, 0, 3, 6, … equals 18?',['sixth','seventh','eighth','ninth'],'C','Here a=−3 and d=3. Set −3+(n−1)3=18, so 3(n−1)=21, n−1=7 and n=8. Checking: −3+7·3=18.')]),
 dict(title='Arithmetic series and means',pages='74–77',idea='The sum of n terms of an arithmetic progression is Sₙ=n[2a+(n−1)d]/2, or Sₙ=n(a+L)/2 when the last term L is known. The arithmetic mean of two numbers x and y is (x+y)/2; equally spaced inserted terms make an arithmetic progression.',problem='Add the first seven terms of 1, 4, 7, … .',steps=[(r'a=1,\quad d=4-1=3,\quad n=7','Identify the first term, common difference and term count.'),(r'S_n=\frac n2[2a+(n-1)d]','Use the arithmetic-series formula.'),(r'S_7=\frac72[2(1)+6(3)]','Substitute each known value before simplifying.'),(r'S_7=\frac72(20)=70','Evaluate the bracket, then multiply.')],answer='S₇=70.',checks=[('Find the arithmetic mean of 8 and 18.',['10','12','13','26'],'C','The middle term must be equally far from both ends: (8+18)/2=26/2=13. Check that 13−8=5 and 18−13=5.'),('What is the sum of the first 7 terms of 1, 4, 7, …?',['49','63','70','77'],'C','Here a=1, d=3, n=7. S₇=7/2[2·1+(7−1)·3]=7/2(20)=70. You can check by adding 1+4+7+10+13+16+19.')]),
 dict(title='Geometric sequences and finite sums',pages='78–81',idea='A geometric progression multiplies by a constant ratio r. Its nth term is Uₙ=ar^(n−1), where a is first term. For r≠1, the finite sum is Sₙ=a(1−rⁿ)/(1−r). Negative ratios alternate signs; a negative term does not make the whole ratio negative unless consecutive terms have opposite signs.',problem='Find the sixth term of 4, −6, 9, … .',steps=[(r'a=4,\quad r=\frac{-6}{4}=-\frac32','Divide the second term by the first to find the ratio.'),(r'U_n=ar^{n-1}','Use the geometric nth-term formula.'),(r'U_6=4\left(-\frac32\right)^5','There are five multiplications after the first term.'),(r'U_6=4\left(-\frac{243}{32}\right)=-\frac{243}{8}','An odd power keeps the negative sign; simplify the fraction.')],answer='U₆=−243/8.',checks=[('What is the common ratio of 4, −6, 9, …?',['−3/2','3/2','−2/3','2'],'A','Divide a term by the preceding term: −6/4=−3/2. Check the next pair: 9/(−6)=−3/2, so the ratio is consistent.'),('What is the sum of the first four terms 2, 4, 8, 16?',['16','28','30','32'],'C','Add directly: 2+4+8+16=30. The formula agrees: a=2, r=2, n=4 gives S₄=2(1−2⁴)/(1−2)=2(−15)/(−1)=30.')]),
 dict(title='Geometric means and infinite sums',pages='79–82',idea='For three positive geometric terms x, m, y, the middle term satisfies m²=xy, so m=√(xy). An infinite geometric series has a finite sum only when |r|<1. Its terms then approach zero and S∞=a/(1−r). If |r|≥1 and a≠0, the terms do not shrink enough for the series to converge.',problem='Find 1/2+1/4+1/8+⋯ .',steps=[(r'a=\frac12,\quad r=\frac{1/4}{1/2}=\frac12','The first term is one half and each new term halves the previous one.'),(r'|r|=\frac12<1','The convergence condition holds, so the infinite-sum formula applies.'),(r'S_{\infty}=\frac{a}{1-r}','Use the formula for a convergent geometric series.'),(r'S_{\infty}=\frac{1/2}{1-1/2}=1','Subtract in the denominator, then divide.')],answer='The infinite sum is 1.',checks=[('What is the sum to infinity of 1/2+1/4+1/8+⋯?',['1/2','1','2','No finite sum'],'B','The first term is 1/2 and ratio is 1/2. Since |r|<1, S∞=a/(1−r)=(1/2)/(1/2)=1.'),('Which geometric series has a finite sum to infinity?',['3+6+12+⋯','1−2+4−⋯','4+2+1+⋯','5+5+5+⋯'],'C','A finite sum requires |r|<1. For 4+2+1+⋯, r=1/2, so it converges. The other ratios have magnitudes 2, 2 and 1, so their terms do not approach zero.')]),
]
lessons=[];questions=[]
for i,t in enumerate(topics,1):
 key=f'mth101-sequences-20261029-{i:02d}'
 blocks=[{'type':'heading','text':'Understand it'},{'type':'paragraph','text':t['idea']},{'type':'heading','text':'Worked example'},{'type':'worked_example','title':'Step by step','problem':t['problem'],'steps':[{'calculation':c,'explanation':e} for c,e in t['steps']],'answer':t['answer'],'check':{'calculation':t['steps'][-1][0],'explanation':'The final calculation matches the required term or sum.'}},{'type':'heading','text':'Review the whole lesson'},{'type':'paragraph','text':'Identify the pattern, choose the correct formula, substitute carefully, and check the answer against the first few terms before reading the feedback.'}]
 for q,opts,correct,why in t['checks']:blocks.append({'type':'checkpoint','question':q,'options':opts,'correct_index':ord(correct)-65,'explanation':why})
 blocks += [{'type':'callout','tone':'example','title':'Key result','text':t['answer']},{'type':'heading','text':'Recap'},{'type':'paragraph','text':t['idea']}]
 lessons.append({'course_code':'MTH 101','module_title':'Sequences and Series','module_position':6,'lesson_position':i,'logical_key':key,'title':t['title'],'objective':'Recognize the pattern and explain each step in the calculation.','estimated_minutes':8,'blocks':blocks,'source_reference':source+', '+t['pages'],'flashcards':[{'front':q,'back':why,'tag':'section'} for q,_,_,why in t['checks']]})
 for j,(q,opts,correct,why) in enumerate(t['checks'],1):questions.append({'logical_question_key':f'{key}-q{j}','pool':'learning','usage':['review','practice','mock'],'prompt':q,'options':[{'label':chr(65+n),'body':o} for n,o in enumerate(opts)],'correct_option':correct,'explanation':why,'course_code':'MTH 101','difficulty':'beginner' if i<3 else 'intermediate','source_reference':source+', '+t['pages']})
(out/'mth-101-sequences-lessons-20261029.json').write_text(json.dumps(lessons,ensure_ascii=False,indent=2)+'\n',encoding='utf8')
bundle=json.loads((out/'mth-101-induction-question-sync-20261029.json').read_text(encoding='utf8'))
bundle['questions']+=questions
(out/'mth-101-sequences-question-sync-20261029.json').write_text(json.dumps(bundle,ensure_ascii=False,indent=2)+'\n',encoding='utf8')
print(f'{len(lessons)} lessons, {len(questions)} new questions, {len(bundle["questions"])} total questions')
